    this.increase_commit = () => {
      if (this.state.ac_investor_name === "") {
        message.warning("Please Select Investor");
        return;
      }

      const {
        ac_amount,
        ac_captable_threshold_amount,
        ac_multiples_of,
        ac_maxamount,
        ac_captable_multiple_amount,
        ac_minamount
      } = this.state;
      let newAmount = Number(ac_amount);
      let changeAmount = 0;

      if (newAmount < ac_captable_threshold_amount && newAmount % ac_multiples_of != 0) {
        const roundedHigherAmount = Math.ceil(newAmount / Number(ac_multiples_of)) * Number(ac_multiples_of);
        newAmount = roundedHigherAmount;
        changeAmount = 0;
      } else if (newAmount > ac_captable_threshold_amount && newAmount % ac_captable_multiple_amount != 0) {
        const roundedHigherAmount = Math.ceil(newAmount / Number(ac_captable_multiple_amount)) * Number(ac_captable_multiple_amount);
        newAmount = roundedHigherAmount;
        changeAmount = 0;
      } else if (newAmount < Number(ac_captable_threshold_amount)) {
        changeAmount = Number(ac_multiples_of);
      } else {
        changeAmount = Number(ac_captable_multiple_amount);
      }

      newAmount += changeAmount;

      if (newAmount > ac_maxamount) {
        newAmount = ac_maxamount;
      } else if (newAmount < ac_minamount) {
        newAmount = Number(ac_minamount);
      }

      this.setState({
        ac_amount: newAmount,
        ac_commaAmount: this.formatNumberWithCommas(newAmount)
      }, () => {
        this.calculategst();
        this.check_for_error();
      });
    };

    this.decrease_commit = () => {
      if (this.state.ac_investor_name === "") {
        message.warning("Please Select Investor");
        return;
      }

      const {
        ac_amount,
        ac_captable_threshold_amount,
        ac_multiples_of,
        ac_minamount,
        ac_captable_multiple_amount
      } = this.state;
      let newAmount = Number(ac_amount);
      let changeAmount;

      if (newAmount == ac_captable_threshold_amount && newAmount % ac_multiples_of != 0) {
        const roundedHigherAmount = Math.ceil(newAmount / Number(ac_multiples_of)) * Number(ac_multiples_of);
        newAmount = roundedHigherAmount;
        changeAmount = 0;
      } else if (newAmount < ac_captable_threshold_amount && newAmount % ac_multiples_of != 0) {
        const roundedLowerAmount = Math.floor(newAmount / Number(ac_multiples_of)) * Number(ac_multiples_of);
        newAmount = roundedLowerAmount;
        changeAmount = 0;
      } else if (newAmount > ac_captable_threshold_amount && newAmount % ac_captable_multiple_amount != 0) {
        const roundedLowerAmount = Math.floor(newAmount / Number(ac_captable_multiple_amount)) * Number(ac_captable_multiple_amount);
        newAmount = roundedLowerAmount;
        changeAmount = 0;
      } else if (newAmount <= Number(ac_captable_threshold_amount)) {
        changeAmount = Number(ac_multiples_of);
      } else {
        changeAmount = Number(ac_captable_multiple_amount);
      }

      newAmount -= changeAmount;

      if (newAmount < ac_minamount) {
        newAmount = ac_minamount;
      }

      this.setState({
        ac_amount: newAmount,
        ac_commaAmount: this.formatNumberWithCommas(newAmount)
      }, () => {
        this.calculategst();
        this.check_for_error();
      });
    };

